import { createClient } from '@supabase/supabase-js'
import { projectId, publicAnonKey } from '../../utils/supabase/info'

/**
 * Browser Supabase client. Uses ONLY the public anon key; every table access is governed by RLS.
 * Config order: VITE_* env vars, then the autogenerated utils/supabase/info.tsx.
 */
const url: string = import.meta.env.VITE_SUPABASE_URL ?? `https://${projectId}.supabase.co`
const anonKey: string = import.meta.env.VITE_SUPABASE_ANON_KEY ?? publicAnonKey

// Hard stop if a privileged key is ever placed in a browser-bundled variable.
function jwtRole(token: string): string | undefined {
  try {
    return JSON.parse(atob(token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/'))).role
  } catch {
    return undefined
  }
}
if (jwtRole(anonKey) === 'service_role') {
  throw new Error('A service-role key was supplied to the browser client. Remove it and rotate the key in Supabase.')
}

export const supabase = createClient(url, anonKey, {
  auth: {
    flowType: 'pkce', // email links return ?code=… (the app uses hash routing, so no #access_token)
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
  },
})

/** Bump together with the last file in supabase/proposed-migrations. */
export const REQUIRED_SCHEMA_VERSION = 10
export const supabaseProjectRef = projectId
